61	// Assume we need to use a bounce buffer to avoid performance problems on Pis running kernel 5.x and using zerocopy
62	#  define USE_BOUNCE_BUFFER
63	#endif
64	
65	static struct {
66	    iq_convert_fn converter;
67	    struct converter_state *converter_state;
68	    rtlsdr_dev_t *dev;
69	    uint8_t *bounce_buffer;
70	    int ppm_error;
71	    bool digital_agc;
72	    bool use_rtl_agc;
73	    int numgains;
74	    int *gains;
75	    int curGain;
76	    int tunerAgcEnabled;
77	} RTLSDR;
78	
79	//
80	// =============================== RTLSDR handling ==========================
81	//
82	
83	void rtlsdrInitConfig() {
84	    RTLSDR.dev = NULL;
85	    RTLSDR.digital_agc = false;
86	    RTLSDR.use_rtl_agc = false;
87	    RTLSDR.ppm_error = 0;
88	    RTLSDR.converter = NULL;
89	    RTLSDR.converter_state = NULL;
90	    RTLSDR.bounce_buffer = NULL;
91	    RTLSDR.numgains = 0;
92	    RTLSDR.gains = NULL;
93	    RTLSDR.tunerAgcEnabled = 0;
94	}
95	
96	static int getClosestGainIndex(int target) {
97	    target = (target == MODES_MAX_GAIN ? 9999 : target);
98	    int closest = 0;
99	
100	    for (int i = 0; i < RTLSDR.numgains; ++i) {
101	        if (abs(RTLSDR.gains[i] - target) < abs(RTLSDR.gains[closest] - target)) {
102	            closest = i;
103	        }
104	    }
105	    return closest;
106	}
107	
108	void rtlsdrSetGain(char *reason) {
109	    if (RTLSDR.use_rtl_agc && (Modes.gain == MODES_AUTO_GAIN || Modes.gain >= 520)) {
110	        Modes.gain = MODES_RTL_AGC;
111	    }
112	
113	    if (Modes.increaseGain || Modes.lowerGain) {
114	        int closest = getClosestGainIndex(Modes.gain);
115	        if (Modes.increaseGain) {
116	            closest += Modes.increaseGain;
117	        }
118	        if (Modes.lowerGain) {
119	            closest -= Modes.lowerGain;
120	        }
121	        if (closest >= RTLSDR.numgains) {
122	            closest = RTLSDR.numgains - 1;
123	        }
124	        if (closest < 0) {
125	            closest = 0;
126	        }
127	        Modes.increaseGain = 0;
128	        Modes.lowerGain = 0;
129	
130	        if (RTLSDR.gains[closest] < Modes.minGain) {
131	            // new gain less than minimum, nothing to do
132	            return;
133	        }
134	        if (Modes.gain == RTLSDR.gains[closest]) {
135	            // same gain, nothing to do
136	            return;
137	        }
138	
139	        // change gain
140	        Modes.gain = RTLSDR.gains[closest];
141	    }
142	
143	    if (Modes.gain < 0) {
144	        Modes.gain = 0;
145	    }
146	
147	    if (RTLSDR.use_rtl_agc && Modes.gain == MODES_RTL_AGC) {
148	
149	        RTLSDR.tunerAgcEnabled = 1;
150	        if (!Modes.gainQuiet) {
151	            fprintf(stderr, "%srtlsdr: tuner gain set to 59.0 dB (tuner AGC)\n", reason);
152	        }
153	        if (rtlsdr_set_tuner_gain_mode(RTLSDR.dev, 0)) {
154	            fprintf(stderr, "rtlsdr: enabling tuner AGC failed\n");
155	            return;
156	        }
157	    } else {
158	
159	        int closest = getClosestGainIndex(Modes.gain);
160	        int newGain = RTLSDR.gains[closest];
161	
162	        if (RTLSDR.tunerAgcEnabled) {
163	            if (rtlsdr_set_tuner_gain_mode(RTLSDR.dev, 1)) {
164	                fprintf(stderr, "rtlsdr: disabling tuner AGC failed\n");
165	                return;
166	            }
167	            RTLSDR.tunerAgcEnabled = 0;
168	            usleep(1000);
169	        }
170	        if (rtlsdr_set_tuner_gain(RTLSDR.dev, newGain)) {
171	            fprintf(stderr, "rtlsdr: setting tuner gain failed\n");
172	            return;
173	        } else {
174	            if (!Modes.gainQuiet) {
175	                fprintf(stderr, "%srtlsdr: tuner gain set to %4.1f dB\n", reason, newGain / 10.0);
176	            }
177	            Modes.gain = newGain;
178	        }
179	    }
180	}
181	
182	static void show_rtlsdr_devices() {
183	    int device_count = rtlsdr_get_device_count();
184	    fprintf(stderr, "rtlsdr: found %d device(s):\n", device_count);
185	    for (int i = 0; i < device_count; i++) {
186	        char vendor[256], product[256], serial[256];
187	
188	        if (rtlsdr_get_device_usb_strings(i, vendor, product, serial) != 0) {
189	            fprintf(stderr, "  %d:  unable to read device details\n", i);
190	        } else {
191	            fprintf(stderr, "  %d:  %s, %s, SN: %s\n", i, vendor, product, serial);
192	        }
193	    }
194	}
195	
196	static int find_device_index(char *s) {
197	    int device_count = rtlsdr_get_device_count();
198	    if (!device_count) {
199	        return -1;
200	    }
201	
202	    /* does string look like raw id number */
203	    if (!strcmp(s, "0")) {
204	        return 0;
205	    } else if (s[0] != '0') {
206	        char *s2;
207	        int device = (int) strtol(s, &s2, 10);
208	        if (s2[0] == '\0' && device >= 0 && device < device_count) {
209	            return device;
210	        }
211	    }
212	
213	    /* does string exact match a serial */
214	    for (int i = 0; i < device_count; i++) {
215	        char serial[256];
216	        if (rtlsdr_get_device_usb_strings(i, NULL, NULL, serial) == 0 && !strcmp(s, serial)) {
217	            return i;
218	        }
219	    }
220	
221	    /* does string prefix match a serial */
222	    for (int i = 0; i < device_count; i++) {
223	        char serial[256];
224	        if (rtlsdr_get_device_usb_strings(i, NULL, NULL, serial) == 0 && !strncmp(s, serial, strlen(s))) {
225	            return i;
226	        }
227	    }
228	
229	    /* does string suffix match a serial */
230	    for (int i = 0; i < device_count; i++) {
231	        char serial[256];
232	        if (rtlsdr_get_device_usb_strings(i, NULL, NULL, serial) == 0 && strlen(s) < strlen(serial) && !strcmp(serial + strlen(serial) - strlen(s), s)) {
233	            return i;
234	        }
235	    }
236	
237	    return -1;
238	}
239	
240	bool rtlsdrHandleOption(int key, char *arg) {
241	    switch (key) {
242	        case OptRtlSdrEnableAgc:
243	            RTLSDR.digital_agc = true;
244	            break;
245	        case OptRtlSdrPpm:
246	            RTLSDR.ppm_error = atoi(arg);
247	            break;
248	        default:
249	            return false;
250	    }
251	    return true;
252	}
253	
254	bool rtlsdrOpen(void) {
255	    if (!rtlsdr_get_device_count()) {
256	        fprintf(stderr, "FATAL: rtlsdr: no supported devices found.\n");
257	        return false;
258	    }
259	
260	    int dev_index = 0;
261	    if (Modes.dev_name) {
262	        if ((dev_index = find_device_index(Modes.dev_name)) < 0) {
263	            fprintf(stderr, "FATAL: rtlsdr: no device matching '%s' found.\n", Modes.dev_name);
264	            show_rtlsdr_devices();
265	            return false;
266	        }
267	    }
268	
269	    char manufacturer[256];
270	    char product[256];
271	    char serial[256];
272	    if (rtlsdr_get_device_usb_strings(dev_index, manufacturer, product, serial) < 0) {
273	        fprintf(stderr, "FATAL: rtlsdr: error querying device #%d: %s\n", dev_index, strerror(errno));
274	        return false;
275	    }
276	
277	    fprintf(stderr, "rtlsdr: using device #%d: %s (%s, %s, SN %s)\n",
278	            dev_index, rtlsdr_get_device_name(dev_index),
279	            manufacturer, product, serial);
280	
281	    if (rtlsdr_open(&RTLSDR.dev, dev_index) < 0) {
282	        fprintf(stderr, "FATAL: rtlsdr: error opening the RTLSDR device: %s\n",
283	                strerror(errno));
284	        return false;
285	    }
286	
287	    RTLSDR.numgains = rtlsdr_get_tuner_gains(RTLSDR.dev, NULL);
288	    if (RTLSDR.numgains <= 0) {
289	        fprintf(stderr, "FATAL: rtlsdr: error getting tuner gains\n");
290	        return false;
291	    }
292	
293	    enum rtlsdr_tuner tuner = rtlsdr_get_tuner_type(RTLSDR.dev);
294	    if (tuner == RTLSDR_TUNER_FC2580 || tuner == RTLSDR_TUNER_FC0012 || tuner == RTLSDR_TUNER_FC0013) {
295	        Modes.bad_tuner = 1;
296	        fprintf(stderr, "\n\nrtlsdr: BAD TUNER, 1090 reception will be TERRIBLE, use another SDR\n\n\n");
297	    }
298	
299	    // allocate numgains + 1 for the AGC being added as a pseudo gain level (hacky)
300	    RTLSDR.gains = cmalloc((RTLSDR.numgains + 1) * sizeof (int));
301	    if (rtlsdr_get_tuner_gains(RTLSDR.dev, RTLSDR.gains) != RTLSDR.numgains) {
302	        fprintf(stderr, "FATAL: rtlsdr: error getting tuner gains\n");
303	        free(RTLSDR.gains);
304	        return false;
305	    }
306	
307	    //fprintf(stderr, "numgains: %d\n", RTLSDR.numgains);
308	    // one extra step for tuner agc / max (but only for rtl tuners)
309	    if (RTLSDR.numgains == 29) {
310	        // this is hacky and relies on the fact that we allocate 1 extra element
311	        RTLSDR.use_rtl_agc = true;
312	        // set agc at 590 (MODES_RTL_AGC)
313	        RTLSDR.gains[RTLSDR.numgains] = MODES_RTL_AGC;
314	        RTLSDR.numgains++;
315	    }
316	
317	    rtlsdrSetGain("");
318	
319	    if (RTLSDR.digital_agc) {
320	        fprintf(stderr, "rtlsdr: enabling digital AGC\n");
321	        rtlsdr_set_agc_mode(RTLSDR.dev, 1);
322	    }
323	
324	    // Set frequency, sample rate, and reset the device
325	
326	    rtlsdr_set_freq_correction(RTLSDR.dev, RTLSDR.ppm_error);
327	    rtlsdr_set_center_freq(RTLSDR.dev, Modes.freq);
328	    rtlsdr_set_sample_rate(RTLSDR.dev, (unsigned) Modes.sample_rate);
329	#ifdef ENABLE_RTLSDR_BIASTEE
330	    // Enable or disable bias tee on GPIO pin 0. (Works only for rtl-sdr.com v3 dongles)
331	    rtlsdr_set_bias_tee(RTLSDR.dev, Modes.biastee);
332	#endif
333	
334	    rtlsdr_reset_buffer(RTLSDR.dev);
335	
336	    RTLSDR.converter = init_converter(INPUT_UC8,
337	            Modes.sample_rate,
338	            Modes.dc_filter,
339	            &RTLSDR.converter_state);
340	    if (!RTLSDR.converter) {
341	        fprintf(stderr, "FATAL: rtlsdr: can't initialize sample converter\n");
342	        rtlsdrClose();
343	        return false;
344	    }
345	
346	#ifdef USE_BOUNCE_BUFFER
347	    if (!(RTLSDR.bounce_buffer = cmalloc(Modes.sdr_buf_size))) {
348	        fprintf(stderr, "FATAL: rtlsdr: can't allocate bounce buffer\n");
349	        rtlsdrClose();
350	        return false;
351	    }
352	#endif
353	
354	    return true;
355	}
356	
357	static struct timespec rtlsdr_thread_cpu;
358	
359	void rtlsdrCallback(unsigned char *buf, uint32_t len, void *ctx) {
360	    struct mag_buf *outbuf;
361	    struct mag_buf *lastbuf;
362	    uint32_t slen;
363	    unsigned next_free_buffer;
364	    unsigned free_bufs;
365	    int64_t block_duration;
366	
367	    static int dropping = 0;
368	    static uint64_t sampleCounter = 0;
369	
370	    static int antiSpam;
371	    static int antiSpam2;
372	
373	    int64_t sysMicroseconds = mono_micro_seconds();
374	    int64_t sysTimestamp = mstime();
375	
376	    // simulating missed USB packets:
377	    if (0) {
378	        static int fail;
379	        if (fail++ % (35 * 20) == 0) {
380	            fprintf(stderr, "ignoring rtsdrCallback\n");
381	            return;
382	        }
383	    }
384	
385	    MODES_NOTUSED(ctx);
386	
387	    // Lock the data buffer variables before accessing them
388	    lockReader();
389	
390	    next_free_buffer = (Modes.first_free_buffer + 1) % MODES_MAG_BUFFERS;
391	    outbuf = &Modes.mag_buffers[Modes.first_free_buffer];
392	    lastbuf = &Modes.mag_buffers[(Modes.first_free_buffer + MODES_MAG_BUFFERS - 1) % MODES_MAG_BUFFERS];
393	    free_bufs = (Modes.first_filled_buffer - next_free_buffer + MODES_MAG_BUFFERS) % MODES_MAG_BUFFERS;
394	
395	    unlockReader();
396	
397	    if (len != Modes.sdr_buf_size) {
398	        static int64_t antiSpam;
399	        if (mstime() > antiSpam) {
400	            antiSpam = mstime() + 10 * SECONDS;
401	            fprintf(stderr, "weirdness: rtlsdr gave us a block with an unusual size (got %u bytes, expected %u bytes), suppressing this message for 10 seconds\n",
402	                    (unsigned) len, (unsigned) Modes.sdr_buf_size);
403	        }
404	        if (len > Modes.sdr_buf_size) {
405	            // wat?! Discard the start.
406	            unsigned discard = (len - Modes.sdr_buf_size + 1) / 2;
407	            outbuf->dropped += discard;
408	            buf += discard * 2;
409	            len -= discard * 2;
410	        }
411	    }
412	    slen = len / 2; // Drops any trailing odd sample, that's OK
413	
414	    if (free_bufs == 0 || (dropping && free_bufs < MODES_MAG_BUFFERS / 2)) {
415	        // FIFO is full. Drop this block.
416	        dropping = 1;
417	        outbuf->dropped += slen;
418	        sampleCounter += slen;
419	
420	        // make extra sure that the decode thread isn't sleeping
421	        wakeDecode();
422	
423	        if (--antiSpam <= 0 && !Modes.exit) {
424	            fprintf(stderr, "FIFO dropped, suppressing this message for 30 seconds.\n");
425	            antiSpam = 300;
426	        }
427	        return;
428	    }
429	    dropping = 0;
430	
431	    // Compute the sample timestamp and system timestamp for the start of the block
432	    outbuf->sampleTimestamp = sampleCounter * 12e6 / Modes.sample_rate;
433	    sampleCounter += slen;
434	
435	    if (Modes.debug_sampleCounter && --antiSpam2 <= 0) {
436	        fprintf(stderr, "sampleTimestamp: %020llu\n", (unsigned long long) outbuf->sampleTimestamp);
437	        antiSpam2 = 3000;
438	    }
439	
440	    // Get the approx system time for the start of this block
441	    block_duration = 1e3 * slen / Modes.sample_rate;
442	
443	    outbuf->sysTimestamp = sysTimestamp;
444	    outbuf->sysMicroseconds = sysMicroseconds;
445	
446	    outbuf->sysTimestamp -= block_duration;
447	    outbuf->sysMicroseconds -= block_duration * 1000;
448	
449	    // Copy trailing data from last block (or reset if not valid)
450	    if (outbuf->dropped == 0) {
451	        memcpy(outbuf->data, lastbuf->data + lastbuf->length, Modes.trailing_samples * sizeof (uint16_t));
452	    } else {
453	        memset(outbuf->data, 0, Modes.trailing_samples * sizeof (uint16_t));
454	    }
455	
456	#ifdef USE_BOUNCE_BUFFER
457	    // Work around zero-copy slowness on Pis with 5.x kernels
458	    memcpy(RTLSDR.bounce_buffer, buf, slen * 2);
459	    buf = RTLSDR.bounce_buffer;
460	#endif
461	
462	    // Convert the new data
463	    outbuf->length = slen;
464	    RTLSDR.converter(buf, &outbuf->data[Modes.trailing_samples], slen, RTLSDR.converter_state, &outbuf->mean_level, &outbuf->mean_power);
465	
466	    // Push the new data to the demodulation thread
467	    lockReader();
468	
469	    Modes.mag_buffers[next_free_buffer].dropped = 0;
470	    Modes.mag_buffers[next_free_buffer].length = 0; // just in case
471	    Modes.first_free_buffer = next_free_buffer;
472	
473	    // accumulate CPU while holding the mutex, and restart measurement
474	    end_cpu_timing(&rtlsdr_thread_cpu, &Modes.reader_cpu_accumulator);
475	    start_cpu_timing(&rtlsdr_thread_cpu);
476	
477	    wakeDecode();
478	    unlockReader();
479	}
480	
481	void rtlsdrRun() {
482	    if (!RTLSDR.dev) {
483	        return;
484	    }
485	
486	    start_cpu_timing(&rtlsdr_thread_cpu);
487	
488	    rtlsdr_read_async(RTLSDR.dev, rtlsdrCallback, NULL, MODES_RTL_BUFFERS, Modes.sdr_buf_size);
489	    if (!Modes.exit) {
490	        fprintf(stderr,"FATAL: rtlsdr_read_async returned unexpectedly, probably lost the USB device, bailing out\n");
491	    }
492	}
493	
494	void rtlsdrCancel() {
495	    rtlsdr_cancel_async(RTLSDR.dev); // interrupt read_async
496	}
497	
498	void rtlsdrClose() {
499	    if (RTLSDR.dev) {
500	        rtlsdr_close(RTLSDR.dev);
501	        RTLSDR.dev = NULL;
502	    }
503	
504	    if (RTLSDR.converter) {
505	        cleanup_converter(&RTLSDR.converter_state);
506	        RTLSDR.converter = NULL;
507	    }
508	
509	    free(RTLSDR.gains);
510	    free(RTLSDR.bounce_buffer);
511	    RTLSDR.bounce_buffer = NULL;
512	}
